mkdir -p /work/src/main/kotlin/com/example /work/src/test/kotlin/com/example && cd /work && cat > src/main/kotlin/com/example/Main.kt <<'EOF'
package com.example

import java.io.BufferedReader
import java.io.StringReader

fun greet(name: String): String = "Hello, $name!"

/** Counts lines using `use`, which closes the reader via kotlin-stdlib-jdk7's AutoCloseable support. */
fun countLines(text: String): Int =
    BufferedReader(StringReader(text)).use { reader -> reader.readLines().size }

fun main(args: Array<String>) {
    println(greet(args.firstOrNull() ?: "World"))
}
EOF
cat > src/test/kotlin/com/example/MainTest.kt <<'EOF'
package com.example

import kotlin.test.Test
import kotlin.test.assertEquals

class MainTest {
    @Test
    fun greetsByName() {
        assertEquals("Hello, Kotlin!", greet("Kotlin"))
    }

    @Test
    fun countsLines() {
        assertEquals(3, countLines("a\nb\nc"))
    }
}
EOF
